    h.style.setProperty('stroke-width', '14px', 'important');
    h.style.setProperty('fill', 'none', 'important');
    h.style.setProperty('marker-end', 'none', 'important');
    h.style.pointerEvents = 'stroke'; h.style.cursor = 'pointer';
