  const t = ELEMENT_TINT[isMachineActor(kind) ? 'svc' : 'human'] || {};
  const stroke = t.stroke || '#6b7280', fill = t.fill || '#fff';
  // AN AI AGENT IS A BOT HEAD ON A PERSON'S BODY, and the composition is the meaning: it is a
