  const gapsByDep = {}; for (const g of (dv.gaps || [])) gapsByDep[g.dep] = g.pairs;
  const paneId = (dep) => 'dv-pane-' + dep;
  const rail = [];    // rail button HTML
  const panes = [];   // pane HTML

