    const dot = `<span class="dv-dot${isBus ? ' bus' : ''}${st.rows.length || st.channels.length ? '' : ' ghost'}"></span>`;
    const btn = `<button type="button" class="dv-store" data-pane="${paneId(st.dep)}">${dot}`
